"use client";

import { Icons } from "@/components/icons";
import { buttonVariants } from "@/components/ui/button";
import {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  navigationMenuTriggerStyle,
} from "@/components/ui/navigation-menu";
import { MenuToggleIcon } from "@/components/ui/menu-toggle-icon";
import { useScroll } from "@/components/ui/use-scroll";
import { easeInOutCubic } from "@/lib/animation";
import { siteConfig } from "@/lib/config";
import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useAnimation } from "framer-motion";
import {
  CalendarIcon,
  MessageSquareIcon,
  TrophyIcon,
  UsersIcon,
  BellIcon,
  UserCircleIcon,
  ChevronRight,
  XIcon,
} from "lucide-react";
import Link from "next/link";
import React, { useEffect, useState } from "react";

const features = [
  {
    title: "Trouvez des partenaires",
    href: "#features",
    description: "Connectez-vous avec les membres de votre club selon leur niveau.",
    icon: UsersIcon,
  },
  {
    title: "Organisez vos matchs",
    href: "#features",
    description: "Planifiez vos parties en quelques taps.",
    icon: CalendarIcon,
  },
  {
    title: "Messagerie intégrée",
    href: "#features",
    description: "Discutez directement avec vos partenaires.",
    icon: MessageSquareIcon,
  },
  {
    title: "Défis et récompenses",
    href: "#features",
    description: "Gagnez des Aces en relevant des défis.",
    icon: TrophyIcon,
  },
];

const resources = [
  {
    title: "Tarifs",
    href: "#pricing",
    description: "Gratuit pour les membres, sur devis pour les clubs.",
  },
  {
    title: "FAQ",
    href: "#faq",
    description: "Réponses aux questions fréquentes.",
  },
  {
    title: "Témoignages",
    href: "#testimonials",
    description: "Ce que nos utilisateurs disent de nous.",
  },
];

export function Header() {
  const [isVisible, setIsVisible] = useState(true);
  const [addBorder, setAddBorder] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const controls = useAnimation();

  useEffect(() => {
    let lastScrollY = 0;

    const handleScroll = () => {
      const currentScrollY = window.scrollY;
      setIsVisible(currentScrollY <= lastScrollY);
      setAddBorder(currentScrollY > 20);
      lastScrollY = currentScrollY;
    };

    window.addEventListener("scroll", handleScroll);
    setIsInitialLoad(false);

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  useEffect(() => {
    controls.start(isVisible ? "visible" : "hidden");
  }, [isVisible, controls]);

  const headerVariants = {
    hidden: { opacity: 0, y: "-100%" },
    visible: { opacity: 1, y: 0 },
  };

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.header
          initial="hidden"
          animate={controls}
          exit="hidden"
          variants={headerVariants}
          transition={{
            duration: isInitialLoad ? 1 : 0.3,
            delay: isInitialLoad ? 0.5 : 0,
            ease: easeInOutCubic,
          }}
          className={cn("sticky top-0 z-50 p-0 bg-background/60 backdrop-blur")}
        >
          <div className="flex justify-between items-center container mx-auto p-2">
            {/* Logo */}
            <Link
              href="/"
              title="brand-logo"
              className="relative mr-6 flex items-center space-x-2"
            >
              <Icons.logo className="h-8 w-8" />
              <span className="font-bold text-xl">{siteConfig.name}</span>
            </Link>

            {/* Navigation Desktop */}
            <div className="hidden lg:flex items-center gap-2">
              <NavigationMenu>
                <NavigationMenuList>
                  {/* Fonctionnalités */}
                  <NavigationMenuItem>
                    <NavigationMenuTrigger>Fonctionnalités</NavigationMenuTrigger>
                    <NavigationMenuContent>
                      <ul className="grid w-[400px] gap-3 p-4 md:w-[500px] md:grid-cols-2 lg:w-[600px]">
                        {features.map((feature) => (
                          <ListItem
                            key={feature.title}
                            title={feature.title}
                            href={feature.href}
                            icon={feature.icon}
                          >
                            {feature.description}
                          </ListItem>
                        ))}
                      </ul>
                    </NavigationMenuContent>
                  </NavigationMenuItem>

                  {/* À propos */}
                  <NavigationMenuItem>
                    <NavigationMenuTrigger>À propos</NavigationMenuTrigger>
                    <NavigationMenuContent>
                      <ul className="grid w-[250px] gap-3 p-4">
                        {resources.map((resource) => (
                          <ListItem
                            key={resource.title}
                            href={resource.href}
                            title={resource.title}
                          >
                            {resource.description}
                          </ListItem>
                        ))}
                      </ul>
                    </NavigationMenuContent>
                  </NavigationMenuItem>

                  {/* Légal */}
                  <NavigationMenuItem>
                    <NavigationMenuTrigger>Légal</NavigationMenuTrigger>
                    <NavigationMenuContent>
                      <ul className="grid w-[200px] gap-3 p-4">
                        <ListItem href="/cgu" title="CGU">
                          Conditions générales d'utilisation
                        </ListItem>
                        <ListItem href="/privacy" title="Confidentialité">
                          Politique de protection des données
                        </ListItem>
                      </ul>
                    </NavigationMenuContent>
                  </NavigationMenuItem>

                  {/* Contact direct */}
                  <NavigationMenuItem>
                    <Link href="/contact" legacyBehavior passHref>
                      <NavigationMenuLink className={navigationMenuTriggerStyle()}>
                        Contact
                      </NavigationMenuLink>
                    </Link>
                  </NavigationMenuItem>
                </NavigationMenuList>
              </NavigationMenu>

              {/* CTA Button */}
              <Link
                href="/contact"
                className={cn(
                  buttonVariants({ variant: "default" }),
                  "h-9 text-white rounded-full group ml-4"
                )}
              >
                {siteConfig.cta}
              </Link>
            </div>

            {/* Mobile Menu */}
            <div className="mt-2 cursor-pointer block lg:hidden">
              <MobileDrawer />
            </div>
          </div>
          <motion.hr
            initial={{ opacity: 0 }}
            animate={{ opacity: addBorder ? 1 : 0 }}
            transition={{ duration: 0.2, ease: "easeInOut" }}
            className="absolute w-full bottom-0"
          />
        </motion.header>
      )}
    </AnimatePresence>
  );
}

const ListItem = React.forwardRef<
  React.ElementRef<"a">,
  React.ComponentPropsWithoutRef<"a"> & { icon?: React.ComponentType<{ className?: string }> }
>(({ className, title, children, icon: Icon, ...props }, ref) => {
  return (
    <li>
      <NavigationMenuLink asChild>
        <a
          ref={ref}
          className={cn(
            "block select-none space-y-1 rounded-md p-3 leading-none no-underline outline-none transition-colors hover:bg-accent hover:text-accent-foreground focus:bg-accent focus:text-accent-foreground",
            className
          )}
          {...props}
        >
          <div className="flex items-center gap-2">
            {Icon && <Icon className="h-4 w-4 text-primary" />}
            <div className="text-sm font-medium leading-none">{title}</div>
          </div>
          <p className="line-clamp-2 text-sm leading-snug text-muted-foreground mt-1">
            {children}
          </p>
        </a>
      </NavigationMenuLink>
    </li>
  );
});
ListItem.displayName = "ListItem";
